const contacts = $input.all().map(i => i.json);
if (!contacts.length || !contacts[0].id) return [];

// Format for Google Sheets (flat structure)
return contacts.map(c => ({
  json: {
    ID: c.id,
    Email: c.email,
    'First Name': c.first_name || '',
    'Last Name': c.last_name || '',
    Company: c.company || '',
    'Job Title': c.job_title || '',
    Phone: c.phone || '',
    'Lead Score': c.lead_score || 0,
    Status: c.lead_status || 'new',
    Source: c.source || '',
    'Created Date': c.created_date || '',
    'Total Activities': c.total_activities || 0,
    'Last Activity': c.last_activity_date || ''
  }
}));
